// Copy page as Markdown: adds a button that copies the Markdown copy of the
// current page (its URL with .md added) to the clipboard. No dependencies,
// no requests to other sites. Generated by docsbot agent-ready generate.
(function () {
  function markdownURL(p) {
    p = p.replace(/\/index\.html?$/, '/').replace(/\.html?$/, '');
    if (p === '' || p === '/') return '/index.md';
    return p.replace(/\/$/, '') + '.md';
  }
  function add() {
    var target = document.querySelector('[data-copy-markdown]') || document.querySelector('main h1') || document.querySelector('h1');
    if (!target) return;
    var b = document.createElement('button');
    b.type = 'button';
    b.className = 'copy-markdown';
    b.textContent = 'Copy page as Markdown';
    b.addEventListener('click', function () {
      fetch(markdownURL(location.pathname))
        .then(function (r) { if (!r.ok) throw new Error(r.status); return r.text(); })
        .then(function (t) { return navigator.clipboard.writeText(t); })
        .then(function () { b.textContent = 'Copied'; setTimeout(function () { b.textContent = 'Copy page as Markdown'; }, 2000); })
        .catch(function () { b.textContent = 'Markdown copy not available'; });
    });
    target.insertAdjacentElement('afterend', b);
  }
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', add); else add();
})();
